// Turns the retention periods into cutoff dates.
// Both values are checked before anything is deleted.
const MIN_DAYS = 30;
const settings = $input.first().json;

function cutoffFor(name) {
  const days = settings[name];
  if (!Number.isInteger(days) || days < MIN_DAYS) {
    throw new Error(`${name} must be a whole number of at least ${MIN_DAYS} days, got ${JSON.stringify(days)}. Nothing was deleted.`);
  }
  return $now.minus({ days }).toUTC().toISO();
}

return [{
  json: {
    ...settings,
    auditCutoff: cutoffFor('auditRetentionDays'),
    errorCutoff: cutoffFor('errorRetentionDays'),
    paymentCutoff: cutoffFor('paymentRetentionDays'),
  },
}];
